 15	/** Deterministic format validation for an API key by provider. No network — a
 16	 *  malformed key is rejected immediately; a well-formed one passes as plausible. */
 17	export function validateApiKeyFormat(provider: string, value: string): { valid: boolean; detail: string } {
 18	  const v = (value ?? "").trim();
 19	  if (!v) return { valid: false, detail: "Empty key." };
 20	  const rule: Record<string, RegExp> = {
 21	    Anthropic: /^sk-ant-[A-Za-z0-9_-]{20,}$/,
 22	    OpenAI: /^sk-[A-Za-z0-9_-]{20,}$/,
 23	    "Kimi (Moonshot)": /^sk-[A-Za-z0-9_-]{20,}$/,
 24	    Resend: /^re_[A-Za-z0-9_-]{10,}$/,
 25	    SendGrid: /^SG\.[A-Za-z0-9_.-]{20,}$/,
 26	    Sillage: /^sk_live_[A-Za-z0-9]{16,}$/,
 27	    Tavily: /^tvly-[A-Za-z0-9_-]{8,}$/,
 28	  };
 29	  const re = rule[provider];
 30	  if (!re) return { valid: v.length >= 8, detail: v.length >= 8 ? "Accepted (custom)." : "Too short." };
 31	  return re.test(v)
 32	    ? { valid: true, detail: `${provider} key format looks valid.` }
 33	    : { valid: false, detail: `Does not match the expected ${provider} key format.` };
 34	}
