 41	/* ============================================================================
 42	   Email provider adapters (SERVER ONLY).
 43	   Dry-run is the default everywhere. A real send happens ONLY when: live mode is
 44	   on, the seat's domain is verified, an API key is present in server env, and the
 45	   request is explicitly confirmed live. Resend / SendGrid send via their official
 46	   REST APIs with a single API key. Microsoft Graph / Gmail require per-mailbox
 47	   OAuth (connect flow) and remain a documented seam — never a fake send.
 48	   No scraping, no LinkedIn automation — email only.
 49	   ========================================================================== */
 50	
 51	export interface SendRequest {
 52	  provider: SeatProvider;
 53	  from: string;
 54	  fromName?: string;
 55	  to: string;
 56	  subject: string;
 57	  body: string;
 58	  /** Server-generated opaque recipient link; required for any live delivery. */
 59	  unsubscribeUrl?: string;
 60	}
 61	
 62	export interface SendOutcome {
 63	  status: "sent" | "dry-run" | "error";
 64	  provider: SeatProvider;
 65	  detail: string;
 66	  id?: string;
 67	}
 68	
 69	/** Perform a real send via the provider's official API. Throws on misconfig. */
 70	export async function sendViaProvider(req: SendRequest): Promise<SendOutcome> {
 71	  auditLog("info", "Send attempt", { provider: req.provider, from: req.from, to: req.to });
 72	  if (!req.unsubscribeUrl) {
 73	    return {
 74	      status: "error",
 75	      provider: req.provider,
 76	      detail: "No compliant unsubscribe link is configured for this email.",
 77	    };
 78	  }
 79	  const rendered = renderEmailWithUnsubscribe(req.body, req.unsubscribeUrl);
 80	  switch (req.provider) {
 81	    case "Resend": {
 82	      const key = process.env.RESEND_API_KEY;
 83	      if (!key) {
 84	        auditLog("info", "Resend dry-run: no API key", { to: req.to });
 85	        return { status: "dry-run", provider: req.provider, detail: "No RESEND_API_KEY, dry-run only." };
 86	      }
 87	      const res = await fetch("https://api.resend.com/emails", {
 88	        method: "POST",
 89	        signal: AbortSignal.timeout(15_000),
 90	        headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
 91	        body: JSON.stringify({
 92	          from: req.fromName ? `${req.fromName} <${req.from}>` : req.from,
 93	          to: [req.to],
 94	          subject: req.subject,
 95	          text: rendered.text,
 96	          html: rendered.html,
 97	          headers: rendered.headers,
 98	        }),
 99	      });
100	      const json = await res.json().catch(() => ({}));
101	      if (!res.ok) {
102	        auditLog("error", "Resend send failed", { status: res.status, to: req.to });
103	        return { status: "error", provider: req.provider, detail: `Resend send error ${res.status}.` };
104	      }
105	      auditLog("info", "Resend send succeeded", { to: req.to, id: json?.id });
106	      return { status: "sent", provider: req.provider, detail: "Sent via Resend.", id: json?.id };
107	    }
108	    case "SendGrid": {
109	      const key = process.env.SENDGRID_API_KEY;
110	      if (!key) {
111	        auditLog("info", "SendGrid dry-run: no API key", { to: req.to });
112	        return { status: "dry-run", provider: req.provider, detail: "No SENDGRID_API_KEY, dry-run only." };
113	      }
114	      const res = await fetch("https://api.sendgrid.com/v3/mail/send", {
115	        method: "POST",
116	        signal: AbortSignal.timeout(15_000),
117	        headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
118	        body: JSON.stringify({
119	          personalizations: [{ to: [{ email: req.to }] }],
120	          from: { email: req.from, name: req.fromName },
121	          subject: req.subject,
122	          content: [
123	            { type: "text/plain", value: rendered.text },
124	            { type: "text/html", value: rendered.html },
125	          ],
126	          headers: rendered.headers,
127	        }),
128	      });
129	      if (!res.ok) {
130	        const txt = await res.text().catch(() => "");
131	        auditLog("error", "SendGrid send failed", { status: res.status, to: req.to, body: redactSecrets(redactEmail(txt.slice(0, 500))) });
132	        return { status: "error", provider: req.provider, detail: `SendGrid send error ${res.status}.` };
133	      }
134	      auditLog("info", "SendGrid send succeeded", { to: req.to });
135	      return { status: "sent", provider: req.provider, detail: "Sent via SendGrid." };
136	    }
137	    case "Microsoft Graph":
138	    case "Gmail API": {
139	      // OAuth providers are handled by sendViaOAuthProvider in the outreach send
140	      // route so the stored token can be resolved server-side.
141	      const detail = `${req.provider} must be sent via the OAuth adapter. Dry-run.`;
142	      auditLog("info", "OAuth provider dry-run", { provider: req.provider, to: req.to });
143	      return { status: "dry-run", provider: req.provider, detail };
144	    }
145	    default:
146	      auditLog("error", "Unknown email provider", { provider: req.provider });
147	      return { status: "dry-run", provider: req.provider, detail: "Unknown provider, dry-run only." };
148	  }
149	}

