128	/**
129	 * Assert a URL is safe to fetch as a PUBLIC resource. Resolves DNS for hostnames
130	 * and rejects if any address is private. Returns { ok:false, reason } on any block.
131	 */
132	export async function assertPublicUrl(
133	  urlString: string,
134	): Promise<{ ok: boolean; reason?: string; hostname?: string }> {
135	  let url: URL;
136	  try {
137	    url = new URL(urlString);
138	  } catch {
139	    return { ok: false, reason: "Invalid URL." };
140	  }
141	  if (url.protocol !== "http:" && url.protocol !== "https:") {
142	    return { ok: false, reason: "Only http/https URLs are allowed." };
143	  }
144	  if (url.username || url.password) {
145	    return { ok: false, reason: "Credentials embedded in the URL are not allowed." };
146	  }
147	  const host = url.hostname.toLowerCase();
148	  const verdict = classifyFetchHost(host);
149	  if (verdict === "blocked") return { ok: false, reason: "Blocked internal/private host (SSRF guard)." };
150	  if (verdict === "public") return { ok: true, hostname: host };
151	  // needs-dns: resolve and ensure every address is public.
152	  try {
153	    const addrs = await lookup(host, { all: true });
154	    if (!addrs.length) return { ok: false, reason: "Host did not resolve." };
155	    for (const a of addrs) {
156	      if (isPrivateIp(a.address)) return { ok: false, reason: "Host resolves to a private address (SSRF guard)." };
157	    }
158	  } catch {
159	    return { ok: false, reason: "DNS resolution failed." };
160	  }
161	  return { ok: true, hostname: host };
162	}

