 5	/**
 6	 * Resolve this workspace's stored, decrypted Tavily key (service-role read -
 7	 * `secret` is withheld from `authenticated` by column grant, same pattern as
 8	 * Apollo/Sillage). Returns null when nothing is stored. Never accepts a raw key
 9	 * from the caller.
10	 */
11	export async function resolveStoredTavilyKey(
12	  session: NonNullable<Awaited<ReturnType<typeof getServerSupabase>>>,
13	  serviceClient = getServiceSupabase(),
14	): Promise<string | null> {
15	  if (!serviceClient) return null;
16	  const { data: wid } = await session.rpc("current_workspace_id");
17	  if (!wid) return null;
18	  const { data: row } = await serviceClient
19	    .from("api_keys")
20	    .select("secret")
21	    .eq("workspace_id", wid)
22	    .eq("provider", "Tavily")
23	    .order("created_at", { ascending: false })
24	    .limit(1)
25	    .maybeSingle();
26	  if (!row?.secret || typeof row.secret !== "string") return null;
27	  const key = decryptSecret(row.secret);
28	  return key || null;
29	}

