 16	/**
 17	 * Real candidate sourcing.
 18	 *
 19	 * platform "GitHub" (default): searches GitHub for real people via the Users
 20	 * Search API. Runs keyless by default (GitHub's anonymous API quota, 60
 21	 * req/hour/IP) — no signup required. An optional GITHUB_TOKEN, resolved
 22	 * server-side and never returned to the client, raises that ceiling to 5,000
 23	 * req/hour.
 24	 *
 25	 * platform in {LinkedIn, Stack Overflow, Dribbble, Behance}: no free structured
 26	 * search API exists for these, so real candidates are discovered via the
 27	 * existing compliant web_search tool (site:-scoped), same honesty/read-only
 28	 * guarantees as the chat research tools.
 29	 *
 30	 * platform in {Referral, Talent Pool}: not externally sourceable — these are
 31	 * internal-pipeline concepts, not searched at all.
 32	 *
 33	 * Read-only throughout: never writes to GitHub, never logs into or scrapes a
 34	 * platform, never posts a message.
 35	 *
 36	 * `username` (optional): manual single-profile intake. When present, `query`
 37	 * is ignored entirely and the request resolves that one GitHub login via
 38	 * GET /users/{login} instead of running a search.
 39	 */
 40	const GITHUB_USERNAME_RE = /^[a-zA-Z\d](?:[a-zA-Z\d]|-(?=[a-zA-Z\d])){0,38}$/;
 41	
 42	const SourceSchema = z
 43	  .object({
 44	    query: z.string().min(1).max(256).optional(),
 45	    username: z.string().min(1).max(39).regex(GITHUB_USERNAME_RE, "Not a valid GitHub username.").optional(),
 46	    count: z.number().int().min(1).max(20).default(8),
 47	    platform: z.enum(SOURCE_PLATFORMS).default("GitHub"),
 48	  })
 49	  .refine((data) => Boolean(data.username?.trim()) || Boolean(data.query?.trim()), {
 50	    message: "query or username is required.",
 51	    path: ["query"],
 52	  });
