 54	function publicDemoSourceDenied(req: NextRequest): Response | null {
 55	  if (supabaseEnabled || !demoLoginEnabled) return null;
 56	  if (demoAuthConfigured() && verifyDemoToken(req.cookies.get(DEMO_COOKIE_NAME)?.value)) return null;
 57	  return NextResponse.json({ ok: false, error: "Sign in to use live sourcing." }, { status: 401 });
 58	}
