 60	export async function POST(req: NextRequest) {
 61	  const prodBlock = prodFailClosed();
 62	  if (prodBlock) return prodBlock;
 63	  const demoBlock = publicDemoSourceDenied(req);
 64	  if (demoBlock) return demoBlock;
 65	
 66	  const rl = checkRateLimit(rateLimitKey(req, "source"), { windowMs: 60_000, max: 10 });
 67	  if (!rl.ok) return tooManyRequests(rl.retryAfterSec);
 68	
 69	  let tavilyKey: string | null = null;
 70	
 71	  // Live mode: require an authenticated user with the `source` permission. Demo
 72	  // mode (no backend) is open but still rate-limited.
 73	  if (supabaseEnabled) {
 74	    const supabase = await getServerSupabase();
 75	    if (!supabase) return NextResponse.json({ ok: false, error: "No Supabase client." }, { status: 500 });
 76	    const {
 77	      data: { user },
 78	    } = await supabase.auth.getUser();
 79	    if (!user) return NextResponse.json({ ok: false, error: "Not authenticated." }, { status: 401 });
 80	    const { data: role } = await supabase.rpc("current_profile_role");
 81	    if (!can(role as Role, "source")) {
 82	      return NextResponse.json({ ok: false, error: "Insufficient permissions." }, { status: 403 });
 83	    }
 84	    tavilyKey = await resolveStoredTavilyKey(supabase);
 85	  }
 86	
 87	  const validated = await validateBody(req, SourceSchema, { maxBytes: 10_000 });
 88	  if (!validated.ok) return validated.response;
 89	  const { query, username, count = 8, platform = "GitHub" as const } = validated.data;
 90	
 91	  // Manual single-profile intake: resolve exactly the named GitHub login,
 92	  // ignoring `query` and `count` entirely — this is a lookup, not a search.
 93	  if (username) {
 94	    const token = process.env.GITHUB_TOKEN ?? "";
 95	    try {
 96	      const user = await getGithubUser(username, token);
 97	      if (!user) {
 98	        return NextResponse.json({ ok: false, error: "GitHub user not found." }, { status: 404 });
 99	      }
100	      return NextResponse.json({ ok: true, source: "github", users: [user] });
101	    } catch (err) {
102	      const detail = err instanceof Error ? err.message : "GitHub lookup failed.";
103	      return NextResponse.json({ ok: false, source: "github", error: detail }, { status: 502 });
104	    }
105	  }
106	
107	  // Schema-enforced: username or query is present; username was handled above.
108	  if (!query) return NextResponse.json({ ok: false, error: "query is required." }, { status: 400 });
109	
110	  if (platform === "GitHub") {
111	    const token = process.env.GITHUB_TOKEN ?? "";
112	    try {
113	      const users = await searchGithubUsers(query, count, token);
114	      return NextResponse.json({ ok: true, source: "github", platform, users });
115	    } catch (err) {
116	      // GitHub error bodies never contain the token; keep the client message terse.
117	      const detail = err instanceof Error ? err.message : "GitHub search failed.";
118	      return NextResponse.json({ ok: false, source: "github", platform, error: detail }, { status: 502 });
119	    }
120	  }
121	
122	  if (isWebSearchPlatform(platform)) {
123	    const scopedQuery = ensureWebQueryScope(platform, query);
124	    const result = await runWebTool("web_search", { query: scopedQuery }, { tavilyKey: tavilyKey ?? undefined });
125	    if (!result.ok) {
126	      return NextResponse.json(
127	        { ok: false, source: "web", platform, error: result.error ?? "Web search failed." },
128	        { status: 502 },
129	      );
130	    }
131	    const content = result.content as { results?: { title: string; url: string; snippet: string }[] } | undefined;
132	    const hits = (content?.results ?? []).slice(0, count);
133	    const leads: WebLead[] = hits.map((h) => extractLead(h, platform));
134	    return NextResponse.json({ ok: true, source: "web", platform, leads });
135	  }
136	
137	  // Referral / Talent Pool: internal-pipeline concepts, no external source to search.
138	  return NextResponse.json({ ok: true, source: "mock", platform, users: [] as GithubUser[] });
139	}
