141	/**
142	 * Real connection test for GitHub sourcing. With a token: pings GET /user and
143	 * reports the authenticated identity. Without one: pings the keyless GET
144	 * /rate_limit endpoint (works anonymously) and reports the live 60 req/hour
145	 * quota, so the UI shows real connectivity rather than "add a token to go live" —
146	 * a token is an optional upgrade, not a requirement. Never returns the token.
147	 */
148	export async function GET(req: NextRequest) {
149	  const prodBlock = prodFailClosed();
150	  if (prodBlock) return prodBlock;
151	  const demoBlock = publicDemoSourceDenied(req);
152	  if (demoBlock) return demoBlock;
153	
154	  const rl = checkRateLimit(rateLimitKey(req, "source-probe"), { windowMs: 60_000, max: 20 });
155	  if (!rl.ok) return tooManyRequests(rl.retryAfterSec);
156	
157	  if (supabaseEnabled) {
158	    const supabase = await getServerSupabase();
159	    if (!supabase) return NextResponse.json({ ok: false, error: "No Supabase client." }, { status: 500 });
160	    const {
161	      data: { user },
162	    } = await supabase.auth.getUser();
163	    if (!user) return NextResponse.json({ ok: false, error: "Not authenticated." }, { status: 401 });
164	    const { data: role } = await supabase.rpc("current_profile_role");
165	    if (!can(role as Role, "source")) {
166	      return NextResponse.json({ ok: false, error: "Insufficient permissions." }, { status: 403 });
167	    }
168	  }
169	
170	  const token = process.env.GITHUB_TOKEN ?? "";
171	
172	  if (!token) {
173	    try {
174	      const res = await fetch("https://api.github.com/rate_limit", {
175	        headers: { Accept: "application/vnd.github+json", "User-Agent": "aria-sourcing" },
176	        signal: AbortSignal.timeout(10_000),
177	      });
178	      if (!res.ok) {
179	        return NextResponse.json({ ok: true, connected: false, reason: `GitHub unreachable (${res.status}).` });
180	      }
181	      const body = (await res.json().catch(() => ({}))) as {
182	        resources?: { search?: { remaining?: number; limit?: number } };
183	      };
184	      const search = body.resources?.search;
185	      return NextResponse.json({
186	        ok: true,
187	        connected: true,
188	        login: null,
189	        name: null,
190	        anonymous: true,
191	        rateLimitRemaining: search?.remaining ?? null,
192	        rateLimitTotal: search?.limit ?? null,
193	        reason: "Sourcing anonymously (60 req/hour). Add GITHUB_TOKEN for a higher ceiling (5,000 req/hour).",
194	      });
195	    } catch {
196	      return NextResponse.json({ ok: true, connected: false, reason: "GitHub unreachable." });
197	    }
198	  }
199	
200	  try {
201	    const res = await fetch("https://api.github.com/user", {
202	      headers: {
203	        Authorization: `Bearer ${token}`,
204	        Accept: "application/vnd.github+json",
205	        "X-GitHub-Api-Version": "2022-11-28",
206	        "User-Agent": "aria-sourcing",
207	      },
208	      signal: AbortSignal.timeout(10_000),
209	    });
210	    if (!res.ok) {
211	      return NextResponse.json({ ok: true, connected: false, reason: `GitHub token rejected (${res.status}).` });
212	    }
213	    const u = (await res.json().catch(() => ({}))) as { login?: string; name?: string; public_repos?: number };
214	    return NextResponse.json({
215	      ok: true,
216	      connected: true,
217	      login: u.login ?? "unknown",
218	      name: u.name ?? null,
219	      anonymous: false,
220	      publicRepos: u.public_repos ?? 0,
221	    });
222	  } catch {
223	    return NextResponse.json({ ok: true, connected: false, reason: "GitHub unreachable." });
224	  }
225	}

