212	export function isMantuNeedEmail(text: string): boolean {
213	  return /this need is now|key required skills/i.test(text) || /^\s*recruiter\s*:/im.test(text);
214	}
215	
216	/** Does an inbound mailbox message look like a hiring need / JD email (vs a
217	 *  candidate reply, newsletter, …)? Used by the intake "Scan inbox" flow to
218	 *  pick need emails out of a synced mailbox. Mantu "need is now ACTIVE" mails
219	 *  match on the body; otherwise only a conservative subject-line check — a
220	 *  false positive here would parse a random email into a job brief. */
221	export function isNeedEmail(subject: string, body: string): boolean {
222	  if (isMantuNeedEmail(body) || isMantuNeedEmail(subject)) return true;
223	  return /\b(job description|jd attached|new (role|position|need|vacancy|opening)|hiring request|backfill|open position)\b/i.test(subject);
224	}
225	
226	/** Structured parser for the Mantu/Amaris "need is now ACTIVE" recruitment email. */
227	export function parseMantuNeed(text: string): ParsedIntake {
228	  const field = (label: string): string =>
229	    text.match(new RegExp(`^\\s*${label}\\s*:\\s*(.+)$`, "im"))?.[1]?.trim() ?? "";
230	
231	  const title =
232	    text.match(/this need is now active\s*:?\s*(.+)/i)?.[1]?.trim() ||
233	    field("Subject") ||
234	    field("Need") ||
235	    "Consulting Need";

