 12	
 13	// Auth-gated, never cacheable — without this Next tries to prerender the route at
 14	// build time (calling auth/session helpers before it touches any request API Next
 15	// would otherwise auto-detect as dynamic), which throws the production
 16	// fail-closed guard as a build error when Supabase isn't configured. (Same fix
 17	// already applied to /auth/google and /auth/microsoft.)
 18	export const dynamic = "force-dynamic";
 19	
 20	const DustRunSchema = z.object({
 21	  task: z.enum(DUST_TASKS),
 22	  message: z.string().min(1).max(20_000),
 23	});
 24	
 25	/**
 26	 * Resolve this workspace's persisted Dust config (settings.dust) server-side.
 27	 * Dust is configured entirely through Settings (Configure modal), never passed
 28	 * by the caller, so a client can only pick WHICH task to run — never which
 29	 * workspace/agent/key to spend against.
 30	 */
 31	async function loadDustSettings(
 32	  session: NonNullable<Awaited<ReturnType<typeof getServerSupabase>>>,
 33	): Promise<HermesState["settings"]["dust"] | null> {
 34	  const { data: wid } = await session.rpc("current_workspace_id");
 35	  if (!wid) return null;
 36	  const { data: row } = await session
 37	    .from("workspace_state")
 38	    .select("state")
 39	    .eq("workspace_id", wid)
 40	    .maybeSingle();
 41	  const state = row?.state as HermesState | undefined;
 42	  return state?.settings?.dust ?? null;
 43	}
 44	
 45	/** Resolve a vault secret by ApiKey.id, scoped to the caller's workspace. Returns
 46	 *  "" on any failure. NEVER logs or returns the value outside the immediate call. */
 47	async function resolveVaultSecret(
 48	  session: NonNullable<Awaited<ReturnType<typeof getServerSupabase>>>,
 49	  id?: string,
 50	): Promise<string> {
 51	  if (!id) return "";
 52	  const svc = getServiceSupabase();
 53	  if (!svc) return "";
 54	  const { data: wid } = await session.rpc("current_workspace_id");
