 62	/**
 63	 * Run a Dust agent for one recruiting task (jdAnalysis / companyResearch). The
 64	 * workspace id, API key, and which agent is locked to the task are all resolved
 65	 * server-side from the caller's persisted Settings — the request body carries
 66	 * only the task and the message text.
 67	 */
 68	export async function POST(req: NextRequest) {
 69	  // Fail closed in production (middleware doesn't cover /api/*).
 70	  const prodBlock = prodFailClosed();
 71	  if (prodBlock) return prodBlock;
 72	
 73	  // Auth-first: reject unauthenticated / under-permissioned callers before
 74	  // buffering the body or spending the workspace's Dust message quota.
 75	  let session: Awaited<ReturnType<typeof getServerSupabase>> = null;
 76	  if (supabaseEnabled) {
 77	    session = await getServerSupabase();
 78	    if (!session) return NextResponse.json({ ok: false, error: "No Supabase client." }, { status: 500 });
 79	    const {
 80	      data: { user },
 81	    } = await session.auth.getUser();
 82	    if (!user) return NextResponse.json({ ok: false, error: "Not authenticated." }, { status: 401 });
 83	    const { data: role } = await session.rpc("current_profile_role");
 84	    if (!can(role as Role, "source")) {
 85	      return NextResponse.json({ ok: false, error: "Insufficient permissions." }, { status: 403 });
 86	    }
 87	  }
 88	
 89	  // Throttle: runs spend the workspace's shared Dust message quota (~100/day/seat).
 90	  const limit = checkRateLimit(rateLimitKey(req, "dust-run"), { windowMs: 60_000, max: 15 });
 91	  if (!limit.ok) return tooManyRequests(limit.retryAfterSec);
 92	
 93	  const validated = await validateBody(req, DustRunSchema, { maxBytes: 32_000 });
 94	  if (!validated.ok) return validated.response;
 95	  const { task, message } = validated.data;
 96	
 97	  // Demo mode (no Supabase): Dust config lives only in the persisted workspace
 98	  // document, which doesn't exist without a backend — nothing to resolve.
 99	  if (!supabaseEnabled || !session) {
100	    return NextResponse.json({ ok: false, error: "No Dust agent locked for this task." });
101	  }
102	
103	  const dust = await loadDustSettings(session);
104	  const agentSId = dust?.agentLocks?.[task];
105	  if (!dust?.workspaceId || !agentSId) {
106	    return NextResponse.json({ ok: false, error: "No Dust agent locked for this task." });
107	  }
108	
109	  const apiKey = await resolveVaultSecret(session, dust.apiKeyId);
110	  if (!apiKey) {
111	    return NextResponse.json({ ok: false, error: "No Dust API key configured." });
112	  }
113	
114	  const result = await runDustAgent(dust.workspaceId, apiKey, agentSId, message, undefined, dust.region ?? "us");
115	  if (!result.ok) return NextResponse.json({ ok: false, error: result.error });
116	  return NextResponse.json({ ok: true, text: result.text });
117	}

