 17	/**
 18	 * API key storage. Secrets are written to the `api_keys` table (admin-only via
 19	 * RLS) and NEVER returned to the browser. In DEMO mode nothing persists
 20	 * server-side — the response carries only metadata (last4) for the session.
 21	 */
 22	export async function POST(req: NextRequest) {
 23	  // Fail closed in production (middleware doesn't cover /api/*).
 24	  const prodBlock = prodFailClosed();
 25	  if (prodBlock) return prodBlock;
 26	
 27	  // Auth-first: resolve and authorise the caller BEFORE parsing the body or
 28	  // touching the secret. Demo mode (no Supabase) is intentionally open and only
 29	  // echoes metadata.
 30	  let supabase: Awaited<ReturnType<typeof getServerSupabase>> = null;
 31	  let createdBy = "unknown";
 32	  if (supabaseEnabled) {
 33	    supabase = await getServerSupabase();
 34	    if (!supabase) return NextResponse.json({ ok: false, error: "No Supabase client." }, { status: 500 });
 35	    const admin = await requireAdmin(supabase);
 36	    if (!admin.ok) return admin.response;
 37	    const {
 38	      data: { user },
 39	    } = await supabase.auth.getUser();
 40	    createdBy = user?.email ?? "unknown";
 41	  }
 42	
 43	  // Throttle: persisting secrets is sensitive — blunt abuse / accidental loops.
 44	  const limit = checkRateLimit(rateLimitKey(req, "keys-create"), { windowMs: 60_000, max: 20 });
 45	  if (!limit.ok) return tooManyRequests(limit.retryAfterSec);
 46	
 47	  const validated = await validateBody(req, ApiKeyCreateSchema, { maxBytes: 8_000 });
 48	  if (!validated.ok) return validated.response;
 49	  const { name, provider, value } = validated.data;
 50	
 51	  const last4 = last4Of(value);
 52	  const fmt = validateApiKeyFormat(provider, value);
 53	
 54	  if (!supabaseEnabled) {
 55	    return NextResponse.json({
 56	      ok: true,
 57	      demo: true,
 58	      last4,
 59	      formatValid: fmt.valid,
 60	      detail: "Saved for this session (demo). Configure Supabase to persist server-side.",
 61	    });
 62	  }
 63	
 64	  if (!supabase) return NextResponse.json({ ok: false, error: "No Supabase client." }, { status: 500 });
 65	
 66	  // Fail closed: never persist a new secret in cleartext when production requires
 67	  // encryption at rest but DATA_ENCRYPTION_KEY isn't configured.
 68	  if (encryptionRequiredButMissing()) {
 69	    return NextResponse.json(
 70	      { ok: false, error: "Server encryption key is not configured." },
 71	      { status: 503 },
 72	    );
 73	  }
 74	
 75	  const { data: wid } = await supabase.rpc("ensure_workspace");
