 19	/**
 20	 * Classify a live Sillage contents/query probe into a valid/invalid verdict.
 21	 * 401 is the only "bad key" signal Sillage documents — any other status (even
 22	 * 402/403/404/409/422/429) means the key itself authenticated, so it's honestly
 23	 * reported valid with that status's own detail. A network/timeout error falls
 24	 * back to the deterministic format check, flagged as inconclusive.
 25	 */
 26	function classifySillageTest(
 27	  live: Awaited<ReturnType<typeof testSillageConnection>>,
 28	  fallbackFormat: () => { valid: boolean; detail: string },
 29	): { valid: boolean; detail: string } {
 30	  if (live.ok) return { valid: true, detail: `Sillage key accepted (HTTP ${live.status}).` };
 31	  if (live.status === 401) return { valid: false, detail: live.detail || live.title || "Sillage rejected this key (401)." };
 32	  if (live.status === 0) {
 33	    const fmt = fallbackFormat();
 34	    return { valid: fmt.valid, detail: `${fmt.detail} Sillage was unreachable, format check only.` };
 35	  }
 36	  return { valid: true, detail: live.detail || live.title || `Sillage responded (HTTP ${live.status}).` };
 37	}
