 66	/**
 67	 * Test an API key. Either test a value passed directly (just-entered), or test a
 68	 * stored key by id — the secret is read server-side via the service-role client
 69	 * (workspace-scoped), validated, and the row's status is updated. Never returns
 70	 * the secret.
 71	 */
 72	export async function POST(req: NextRequest) {
 73	  // Fail closed in production (middleware doesn't cover /api/*).
 74	  const prodBlock = prodFailClosed();
 75	  if (prodBlock) return prodBlock;
 76	
 77	  // Auth-first: when a real backend is configured, require admin BEFORE any work
 78	  // or response. The just-entered "value" format check previously returned to
 79	  // unauthenticated callers — it now sits behind this gate.
 80	  let session: Awaited<ReturnType<typeof getServerSupabase>> = null;
 81	  if (supabaseEnabled) {
 82	    session = await getServerSupabase();
 83	    if (!session) return NextResponse.json({ ok: false, error: "No Supabase client." }, { status: 500 });
 84	    const admin = await requireAdmin(session);
 85	    if (!admin.ok) return admin.response;
 86	  }
 87	
 88	  // Throttle: key testing drives provider/LLM cost — abuse-prone. Tight limit.
 89	  const limit = checkRateLimit(rateLimitKey(req, "keys-test"), { windowMs: 60_000, max: 10 });
 90	  if (!limit.ok) return tooManyRequests(limit.retryAfterSec);
 91	
 92	  const validated = await validateBody(req, ApiKeyTestSchema, { maxBytes: 8_000 });
 93	  if (!validated.ok) return validated.response;
 94	  const { provider, value, id } = validated.data;
 95	
 96	  // Direct value test (e.g. on the entry form) — now behind the auth gate above.
 97	  if (value) {
 98	    if ((provider ?? "") === "Sillage") {
 99	      const live = await testSillageConnection(value);
100	      const result = classifySillageTest(live, () => validateApiKeyFormat(provider ?? "", value));
101	      return NextResponse.json({ ok: true, valid: result.valid, detail: result.detail });
102	    }
103	    if ((provider ?? "") === "Apollo") {
104	      const result = await testApolloKey(value);
105	      return NextResponse.json({ ok: true, valid: result.valid, detail: result.detail });
106	    }
107	    if ((provider ?? "") === "Seamless") {
108	      const result = await testSeamlessKey(value);
109	      return NextResponse.json({ ok: true, valid: result.valid, detail: result.detail });
110	    }
111	    const fmt = validateApiKeyFormat(provider ?? "", value);
112	    return NextResponse.json({ ok: true, valid: fmt.valid, detail: fmt.detail });
113	  }
114	
115	  if (!id) return NextResponse.json({ ok: false, error: "Provide a key value or id." }, { status: 400 });
116	
117	  // Stored-key test by id.
118	  if (!supabaseEnabled) {
119	    return NextResponse.json({ ok: true, valid: true, detail: "Simulated test (demo mode)." });
120	  }
121	  const svc = getServiceSupabase();
122	  if (!session || !svc) {
123	    return NextResponse.json({ ok: false, error: "Service role not configured." }, { status: 500 });
124	  }
125	
126	  const { data: wid } = await session.rpc("current_workspace_id");
127	
128	  const { data: row, error } = await svc
129	    .from("api_keys")
130	    .select("provider, secret, workspace_id")
131	    .eq("id", id)
132	    .single();
133	  if (error || !row) return NextResponse.json({ ok: false, error: "Key not found." }, { status: 404 });
134	  if (row.workspace_id !== wid) return NextResponse.json({ ok: false, error: "Forbidden." }, { status: 403 });
135	
136	  const secret = decryptSecret(row.secret);
137	  let fmt: { valid: boolean; detail: string };
138	  if (row.provider === "Sillage") {
139	    fmt = classifySillageTest(await testSillageConnection(secret), () => validateApiKeyFormat(row.provider, secret));
140	  } else if (row.provider === "Apollo") {
141	    fmt = await testApolloKey(secret);
142	  } else if (row.provider === "Seamless") {
143	    fmt = await testSeamlessKey(secret);
144	  } else {
145	    fmt = validateApiKeyFormat(row.provider, secret);
146	  }
147	  await svc
148	    .from("api_keys")
149	    .update({ status: fmt.valid ? "valid" : "invalid", last_tested_at: new Date().toISOString() })
150	    .eq("id", id);
151	  return NextResponse.json({ ok: true, valid: fmt.valid, detail: fmt.detail });
152	}

