369	function normalizeParsedLocation(raw: string | undefined): string {
370	  if (!raw) return "";
371	  const value = raw
372	    .replace(/\s+/g, " ")
373	    .replace(/^(?:our|the|a|an)\s+/i, "")
374	    .replace(/\s+(?:with|must|who|that|to|for|joining|join|experience|team|department|office)\b.*$/i, "")
375	    .replace(/^[\s:,-]+|[\s.,;:!?)\]]+$/g, "")
376	    .trim();
377	  if (!value || value.length > 80 || !/[a-z]/i.test(value)) return "";
378	  if (NON_LOCATION_VALUES.has(value.toLowerCase())) return "";
379	  if (/^(?:strong|senior|staff|lead|principal|backend|frontend|full[- ]stack|software|data|platform)\b/i.test(value)) return "";
380	  return value
381	    .split(" ")
382	    .map((part) => (part === part.toLowerCase() ? part.replace(/^[a-z]/, (c) => c.toUpperCase()) : part))
383	    .join(" ");
384	}
