+export async function resolveStoredDatabricksSecret(
+  session: NonNullable<Awaited<ReturnType<typeof getServerSupabase>>>,
+  apiKeyId: string | undefined,
+  serviceClient = getServiceSupabase(),
+): Promise<string | null> {
